/*
	World Map #WCCChallenge Earth 250430
	https://openprocessing.org/sketch/2631177
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	drawing horizontal or vertical lines based on noise grid.
	Switching colors depending on land or sea, detecting from map image (cc)

	Lessons learned:
	- lerpColor takes some time -> using array of colors instead
	- not new, but noise() is mostly around center and rare near the borders 0 or 1
    implemented accN() to spread the range a bit by increasing distance from center 0.5

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/


let worldImg, worldGr;
const SZE = 8;
// https://www.w3.org/wiki/CSS3/Color/Extended_color_keywords
const CLRS_SEA = ["midnightblue", "blue", "mediumblue"];
const CLRS_LND = ["darkorange", "olive", "green", "saddlebrown"];

async function setup() {
	worldImg = await loadImage("https://upload.wikimedia.org/wikipedia/commons/1/17/BlankMap-World-noborders.png");
	// createCanvas(worldImg.width, worldImg.height);
	createCanvas(innerWidth, innerHeight);
	worldImg.resize(width/SZE, height/SZE)
	background(4, 4, 12);
	describe("World map out of noise vertical or horizotal lines");	
	frameRate(10);


	worldGr = createGraphics(worldImg.width, worldImg.height)
	worldGr.image(worldImg, 0, 0);
	worldGr.filter(BLUR, 4);
	worldGr.filter(THRESHOLD, 0.9);
	// image(worldGr, 0, 0)

	strokeWeight(1);
	noiseSeed(~~random(999999));
	// // noLoop() removed for animation
}

function draw() {
	background(4, 4, 12);

	stroke("darkorange"); 
	drawLayer(SZE);
}

function drawLayer(SZE) {
	let grid = [];
	const numY = ceil(height/SZE);
	const numX = ceil(width/SZE);

	for (let y = 0, j = 0; y < height; y += SZE, j++) {
		grid[j] = [];
		for (let x = 0, i = 0; x < width; x += SZE, i++) {
			grid[j][i] = 0;

			let n = noise(SZE + x/SZE/12, SZE + y/SZE/12, frameCount/231);

			if (brightness(window.color(worldGr.get(x/SZE, y/SZE))) > 25) {
				n = 1 - n; // n = fract(n + 0.5)
				// stroke(lerpColor(color("blue"), color("aqua"), accN(n))); 
				// stroke("blue")
				stroke(CLRS_SEA[~~(n * CLRS_SEA.length)]);
				// continue;
			} else {
				// stroke(lerpColor(color("darkorange"), color("darkgreen"), accN(n))); 
				// stroke("darkorange")
				stroke(CLRS_LND[~~(n * CLRS_LND.length)]);
			}

			if (n < 0.5) {
				grid[j][i] = 1; // horiz
				line(x, y+SZE, x+SZE, y+SZE); // line(x, y+SZE/2, x+SZE, y+SZE/2);
			} else {
				grid[j][i] = 2; // vert
				line(x+SZE, y, x+SZE, y+SZE); // line(x+SZE/2, y, x+SZE/2, y+SZE);
			}
		}
	}
	// console.log(grid);

	// combine lines
	let numLines = 0;
	if (false)
	for (let j = 0; j < numY; j++) {
		for (let i = 0; i < numX; i++) {
			if (grid[j][i] === 0) continue;
			let currDir = grid[j][i], curX = i, curY = j;
			if (currDir === 1) {
				// horiz
				while(curX < numX && grid[j][curX] == currDir) {
					grid[j][curX] = 0;
					curX++;
					// console.log(`__ ${curX}/${numX} ${grid[j][curX]}/${grid[j][i]}`);
					// if (grid[j][curX] != currDir) break;
				}
				// console.log(`x: ${i} - ${curX}, y: ${j} : '-' (${(curX-i)})`)
				line(i*SZE, j*SZE+SZE, curX*SZE, curY*SZE+SZE);

			} else {
				// vert
				while(curY < numY && grid[curY][i] == currDir) {
					grid[curY][i] = 0;
					curY++;
					// console.log(`__ ${curY}/${numY} ${grid[curY][i]}/${grid[j][i]}`);
					// if (grid[curY][i] != currDir) break;
				}
				// console.log(`x: ${i}, y: ${j} - ${curY} : '|' (${(curY-j)})`)
				line(i*SZE+SZE, j*SZE, i*SZE+SZE, curY*SZE);

			}
			numLines++;
		}		
	}
	// console.log(`numLines: ${numLines}`)
	// console.log(grid)
}

function accN(n, m=0.5, f=1.125) {
	return constrain(m + (m-0.5) * f, 0, 1)
}

function mouseClicked() {
	if (mouseButton === LEFT) {
		setup();
	}
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("epi_worldmap.svg"); // Save the canvas as SVG
	}
}
